export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: "unknown_failure" | "invalid_provider_response" | "repository_failure";
  rejections: Rejection[];
}>;

export interface ServiceResponse {
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found" | "service_unavailable";
      };
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; provider: Provider; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      failedAt: Provider;
      classification: "unknown_failure" | "invalid_provider_response";
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function parseRejections(value: unknown): Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections: Rejection[] = [];
  for (const item of value) {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    rejections.push({ provider: item.provider, reason: item.reason });
  }
  return rejections;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    value.id.length === 0 ||
    typeof value.routeCode !== "string" ||
    value.routeCode.length === 0 ||
    typeof value.parcelGrams !== "number" ||
    !Number.isSafeInteger(value.parcelGrams) ||
    value.parcelGrams <= 0
  ) {
    return undefined;
  }

  const base: ShipmentFields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  };

  if (value.state === "queued") {
    return { ...base, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return {
        ...base,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return { ...base, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections,
      };
  }
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function abortBody(
  shipmentId: string,
  failedAt: AbortBody["failedAt"],
  classification: AbortBody["classification"],
  rejections: Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections,
  };
}

function logAbort(dependencies: ShippingDependencies, body: AbortBody): void {
  dependencies.logger.info({
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: body.rejections,
  });
}

function classifyAtlasRejection(rejected: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(rejected) || typeof rejected.code !== "string") {
    return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
  }
  if (rejected.code === "cannot_ship") {
    if (isRefusalReason(rejected.reason)) {
      return {
        kind: "refused",
        rejection: { provider: "atlas", reason: rejected.reason },
      };
    }
    return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
  }
  if (rejected.code === "rate_limited") {
    if (
      typeof rejected.retryAtMs === "number" &&
      Number.isSafeInteger(rejected.retryAtMs) &&
      rejected.retryAtMs > nowMs
    ) {
      return { kind: "throttled", provider: "atlas", retryAtMs: rejected.retryAtMs };
    }
    return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
}

function classifyBeaconRejection(rejected: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(rejected) || typeof rejected.type !== "string") {
    return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
  }
  if (rejected.type === "rejected") {
    if (isObject(rejected.details) && isRefusalReason(rejected.details.reason)) {
      return {
        kind: "refused",
        rejection: { provider: "beacon", reason: rejected.details.reason },
      };
    }
    return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
  }
  if (rejected.type === "throttled") {
    if (
      isObject(rejected.details) &&
      typeof rejected.details.retryAtMs === "number" &&
      Number.isSafeInteger(rejected.details.retryAtMs) &&
      rejected.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", provider: "beacon", retryAtMs: rejected.details.retryAtMs };
    }
    return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, confirmation: unknown): CarrierOutcome {
  if (
    provider === "atlas" &&
    isObject(confirmation) &&
    typeof confirmation.bookingId === "string" &&
    confirmation.bookingId.length > 0
  ) {
    return { kind: "confirmed", bookingId: confirmation.bookingId };
  }
  if (
    provider === "beacon" &&
    isObject(confirmation) &&
    typeof confirmation.reference === "string" &&
    confirmation.reference.length > 0
  ) {
    return { kind: "confirmed", bookingId: confirmation.reference };
  }
  return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return classifyConfirmation(provider, confirmation);
  } catch (rejected) {
    return provider === "atlas"
      ? classifyAtlasRejection(rejected, nowMs)
      : classifyBeaconRejection(rejected, nowMs);
  }
}

function dispatchedShipment(
  shipment: StoredShipment,
  provider: Provider,
  bookingId: string,
  nowMs: number,
): DispatchedShipment {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "dispatched",
    provider,
    bookingId,
    dispatchedAtMs: nowMs,
  };
}

function deferredShipment(
  shipment: StoredShipment,
  nextProvider: Provider,
  retryAtMs: number,
  rejections: Rejection[],
): DeferredShipment {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "deferred",
    nextProvider,
    retryAtMs,
    rejections,
  };
}

function unavailableShipment(
  shipment: StoredShipment,
  rejections: Rejection[],
): UnavailableShipment {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "unavailable",
    rejections,
  };
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function saveDecision(
    shipment: StoredShipment,
    next: StoredShipment,
    rejections: Rejection[],
  ): Promise<ServiceResponse | undefined> {
    try {
      await dependencies.repository.save(shipment.id, next);
    } catch {
      const body = abortBody(shipment.id, "repository", "repository_failure", rejections);
      logAbort(dependencies, body);
      return { status: 500, body };
    }
    return undefined;
  }

  async function persistDispatched(
    shipment: StoredShipment,
    provider: Provider,
    bookingId: string,
    nowMs: number,
    rejections: Rejection[],
  ): Promise<ServiceResponse> {
    const next = dispatchedShipment(shipment, provider, bookingId, nowMs);
    const saveFailure = await saveDecision(shipment, next, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "dispatched",
      provider,
    });
    return { status: 200, body: publicShipment(next) };
  }

  async function persistDeferred(
    shipment: StoredShipment,
    provider: Provider,
    retryAtMs: number,
    rejections: Rejection[],
  ): Promise<ServiceResponse> {
    const next = deferredShipment(shipment, provider, retryAtMs, rejections);
    const saveFailure = await saveDecision(shipment, next, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "deferred",
      provider,
      retryAtMs,
      rejections,
    });
    return { status: 202, body: publicShipment(next) };
  }

  async function persistUnavailable(
    shipment: StoredShipment,
    rejections: Rejection[],
  ): Promise<ServiceResponse> {
    const next = unavailableShipment(shipment, rejections);
    const saveFailure = await saveDecision(shipment, next, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "unavailable",
      rejections,
    });
    return { status: 422, body: publicShipment(next) };
  }

  function abortResponse(
    shipmentId: string,
    failedAt: AbortBody["failedAt"],
    classification: AbortBody["classification"],
    rejections: Rejection[],
  ): ServiceResponse {
    const body = abortBody(shipmentId, failedAt, classification, rejections);
    logAbort(dependencies, body);
    return { status: 500, body };
  }

  async function dispatchFrom(
    shipment: StoredShipment,
    provider: Provider,
    rejections: Rejection[],
    command: Extract<Command, { op: "dispatch" }>,
  ): Promise<ServiceResponse> {
    if (rejections.some((rejection) => rejection.provider === provider)) {
      return abortResponse(shipment.id, provider, "invalid_provider_response", rejections);
    }

    const outcome = await attemptCarrier(
      dependencies,
      provider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    switch (outcome.kind) {
      case "confirmed":
        return persistDispatched(
          shipment,
          provider,
          outcome.bookingId,
          command.nowMs,
          rejections,
        );
      case "throttled":
        return persistDeferred(shipment, outcome.provider, outcome.retryAtMs, rejections);
      case "aborted":
        return abortResponse(
          shipment.id,
          outcome.failedAt,
          outcome.classification,
          rejections,
        );
      case "refused": {
        const nextRejections = [...rejections, outcome.rejection];
        if (provider === "atlas") {
          return dispatchFrom(shipment, "beacon", nextRejections, command);
        }
        return persistUnavailable(shipment, nextRejections);
      }
    }
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return abortResponse(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return abortResponse(command.shipmentId, "repository", "repository_failure", []);
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return dispatchFrom(shipment, shipment.nextProvider, shipment.rejections, command);
    }

    return dispatchFrom(shipment, "atlas", [], command);
  }

  return { handle };
}
